#!/usr/bin/env bash\nset -euo pipefail\n\n# Determine target directory (default current)\nTARGET_DIR="${1:-.}"\n\n# Get du output: either from mock env var or real du\nif [[ -n "${MOCK_DU_OUTPUT:-}" ]]; then\n  DU_OUTPUT="${MOCK_DU_OUTPUT}"\nelse\n  DU_OUTPUT=$(du -b --max-depth=1 "${TARGET_DIR}")\nfi\n\n# Read sizes and names into arrays\ndeclare -a NAMES\ndeclare -a SIZES\nwhile IFS=$'\t' read -r size path; do\n  NAMES+=("${path}")\n  SIZES+=("${size}")\n done <<< "$DU_OUTPUT"\n\n# Find max size\nMAX_SIZE=0\nfor sz in "${SIZES[@]}"; do\n  (( sz > MAX_SIZE )) && MAX_SIZE=$sz\n done\n\n# Function to convert bytes to human readable (simple)\nbytes_to_human() {\n  local b=$1\n  if (( b < 1024 )); then\n    echo "${b}B"\n  elif (( b < 1048576 )); then\n    printf "%.1fKB\n" "$(echo "$b/1024" | bc -l)"\n  else\n    printf "%.1fMB\n" "$(echo "$b/1048576" | bc -l)"\n  fi\n}\n\n# Print each line with bar\nMAX_BAR=40\nfor i in "${!NAMES[@]}"; do\n  size=${SIZES[i]}\n  name=${NAMES[i]}\n  # Compute bar length\n  if (( MAX_SIZE == 0 )); then\n    bar_len=0\n  else\n    bar_len=$(( size * MAX_BAR / MAX_SIZE ))\n  fi\n  # Build bar string\n  bar=$(printf "%${bar_len}s" "" | tr " " "#")\n  human=$(bytes_to_human "$size")\n  printf "%s  %s %s\n" "$human" "$bar" "$name"\n done
